def helper(x): return x * 2

def format_output(s):
    """
    对输出数据进行HTML转义，防止XSS攻击
    移除或编码可能造成安全问题的特殊字符
    """
    # 转换为字符串并去除首尾空白
    s = str(s).strip()

    # HTML转义，防止XSS攻击
    # 编码以下特殊字符:
    # < -> &lt;
    # > -> &gt;
    # & -> &amp;
    # " -> &quot;
    # ' -> &#x27;
    s = html.escape(s, quote=True)

    return s

